  test_id?: string;
  schedule_id?: string;
  title?: string;
  start_time?: string;
  end_time?: string;
  scheduleTest?: string;
  schedule_sort_time?: number;
  duration_mins?: number;
  total_questions?: number;
  total_marks?: number;
  published?: boolean;
  pass_mark?: number;
  number_of_attempts?: number;
  user_attempt?: number;
  attempts_history?: any[];
  target_attempt_number?: number;
  type?: string;
  user_review?: boolean;
  review_available?: boolean;
  review_attempt_id?: string;
  review_mode?: string;
  multiple_review?: boolean;
  attempted?: boolean;
